var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var rig=root.GetComponent<Character.Control.PaddleCharacterVisual>();var scales=new System.Collections.Generic.Dictionary<string,float>();float maxScaleChange=0,error=0,maxJointGap=0;
 foreach(float g in new[]{.65f,1f,1.5f})foreach(float reach in new[]{.75f,1.05f,1.975f})for(int i=0;i<=360;i++){
  var q=UnityEngine.Quaternion.Euler(0,0,i);rig.body.localScale=UnityEngine.Vector3.one*7.5f*g;rig.tool.localScale=UnityEngine.Vector3.one*g;
  rig.tool.rotation=q;rig.tool.position=rig.body.position+q*new UnityEngine.Vector3(reach*g,.074f*g,0);rig.Pose();error=UnityEngine.Mathf.Max(error,rig.HandError);
  foreach(var r in root.GetComponentsInChildren<UnityEngine.SpriteRenderer>())if(r==rig.leftUpper||r==rig.rightUpper||r.name.StartsWith("Forearm segment ")||r.name.StartsWith("Grip palm ")){
   float scale=r.transform.lossyScale.x/g;if(!scales.ContainsKey(r.name))scales.Add(r.name,scale);else maxScaleChange=UnityEngine.Mathf.Max(maxScaleChange,UnityEngine.Mathf.Abs(scale-scales[r.name]));
   if(UnityEngine.Mathf.Abs(r.transform.localScale.x-r.transform.localScale.y)>.00001f)throw new System.Exception("Sprite aspect changed");
  }
  var fore=root.GetComponentsInChildren<UnityEngine.SpriteRenderer>().First(r=>r.name=="Forearm segment "+rig.leftLower.name);
  var upperEnd=Character.Control.PaddleCharacterVisual.PixelPosition(rig.leftUpper,new UnityEngine.Vector2(68,70));
  var lowerEnd=Character.Control.PaddleCharacterVisual.PixelPosition(fore,new UnityEngine.Vector2(13,17));
  maxJointGap=UnityEngine.Mathf.Max(maxJointGap,UnityEngine.Vector3.Distance(upperEnd,lowerEnd)/g);
 }
 string log="3249 poses: normalized sprite scale change="+maxScaleChange+" wrist error="+error+" max elbow anchor separation="+maxJointGap+"; all sprite aspect ratios preserved";
 System.IO.File.WriteAllText("scripts/player-fixed-size-20261111/scale.txt",log);UnityEngine.Debug.Log(log);
 if(maxScaleChange>.00001f||error>.001f)throw new System.Exception("Fixed-size regression");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
